#include "runtime.hpp"
#include "cost_workload_family_v2.hpp"
#include <filesystem>
#include <fstream>
#include <iostream>
using namespace pas;using namespace pas::current_rails;using J=nlohmann::json;
int main(int argc,char**argv){try{if(argc!=2||std::filesystem::exists(argv[1]))throw std::runtime_error("fresh seam report required");FakeClock clock;auto rt=std::make_unique<Runtime>(clock);J rows=J::array(),filtered,events=J::array();int frame=0;rt->event_output=[&](J e){if(e.at("event")=="filtered_owner_scene")filtered=e.at("scene");if(e.at("event")=="game_hold_tail_confirmed"||e.at("event")=="game_contact_up"||e.at("event")=="game_contact_cancelled")events.push_back(e);};bool safe=true;for(int i=1;i<=81;++i){frame=i;Frame f;f.sequence=i;f.epoch=f.generation=f.geometry_version=1;f.width=1280;f.height=720;f.stride=3840;f.source_rotation=1;f.capture_complete_ns=f.pixels_ready_ns=1'000'000'000LL+i*20'000'000LL;f.rgb=cost_family_v2::image(i-1,0,cost_family_v2::Control::positive);clock.set(f.capture_complete_ns);safe&=rt->dispatch(f,true);if(i<58||i>67)continue;J measures=J::array();const auto&b=rt->observer.candidate_batch();for(const auto&c:b.candidates){if(!c.note.tail)continue;const auto front=hold_front::measure(f,b.context,c);auto tail=c;tail.note.center=*c.note.tail;tail.note.tail=front.boundary.value_or(c.note.center);const auto rear=hold_front::measure(f,b.context,tail);measures.push_back({{"raw_head",{c.note.center.x,c.note.center.y}},{"raw_tail",{c.note.tail->x,c.note.tail->y}},{"front_measure",hold_front::encode(front)},{"tail_measure",hold_front::encode(rear)}});}rows.push_back({{"frame",i},{"generator_head",cost_family_v2::head(i-1)},{"raw_generator_tail",cost_family_v2::head(i-1)-160},{"current_measures",measures},{"filtered_owner_scene",filtered}});}const bool released=rt->finish();J out={{"schema","pas.current-tail-seam.v1"},{"same_frozen_family_v2",true},{"safe",safe},{"release_verified",released},{"rows",rows},{"owner_events",events},{"device_endpoints",0},{"physical_gold",0}};std::ofstream f(argv[1]);f<<out.dump(2)<<'\n';return !f||!safe||!released?1:0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
